/* =====================================================================
   Spec build · 4.5 Invite v2 · 4.3 Future Club Sapling · 4.4 Year + Journal
   4.6 Money Manager split v2 · 6c CTA rules · menu · edge-state gallery
   ===================================================================== */

/* ================= 4.5 Invite to your grove ================= */
const SUGG=[['jess','Opened your share card'],['priya','In your Future Club'],['marcus','Frequent contact']];
function slotsOpen(){return 1} /* no cap on the grove */
def('inv-pick',()=>{spInit();if(!S.notThem)S.notThem={};const sug=SUGG.filter(([id,r])=>!inGrove(id)&&!S.notThem[id]&&(id!=='marcus'||S.perm.contacts==='full'));
  return {cls:'dark',html:`${topbar({close:true,title:''})}<div class="body"><div class="h1" style="color:#fff">Invite one person.<br>Grow together.</div><p class="p mt8">Their first investment plants a tree beside yours.</p>
  ${slotsOpen()?'':`<div class="lockrow mt16">${ic('lock',16)}Your grove is full. Cancel a waiting invite to free a spot.</div>`}
  ${sug.length&&slotsOpen()?`<div class="sk-sec"><div class="h4">Suggested</div><span class="sm">only you see this</span></div>
   ${sug.map(([id,r])=>`<div class="card dk mt8" style="padding:12px 14px"><div class="row">${av(id,'s')}<div class="grow"><div style="font-weight:600;color:#fff">${PEOPLE[id].full}</div><div class="sm" style="color:var(--sk-sub)">${r}</div></div>
    <button class="btn wh sm" style="height:36px;padding:0 14px" onclick="invStart('${id}')">Invite</button><button class="iconbtn" style="width:36px;height:36px" onclick="S.notThem['${id}']=Date.now();save();refresh();toast('Not suggested again for 90 days')" aria-label="Not them">${ic('close',16)}</button></div></div>`).join('')}`:''}
  ${slotsOpen()?`<div class="sk-sec"><div class="h4">Or</div></div>
  ${skRow(ic('user',18,'color:#74c947'),'Choose from contacts',S.perm.contacts?'Pick one person':'We’ll ask for access first','nav',S.perm.contacts?"go('inv-contacts')":"go('inv-perm')")}
  ${skRow(ic('link',18,'color:#74c947'),'Share a link','Anyone with it can take this spot','nav',"T.ivp='link';T.day=S.day;go('inv-day')")}`:''}
  <div style="height:20px"></div></div>
  ${foot(btn(`${ic('oak',18)} See my grove`,"GSEL=null;home('gt-grove')",'line','style="color:#fff"'),btn('Invite later',"home('gt-grove');toast('You can invite anyone from your grove, anytime')",'ghost'))}`}});
function invStart(id){if(PEOPLE[id].on&&!inGrove(id)&&id!=='mom'&&id!=='dad'&&id!=='priya'){go('inv-existing',{id});return}T.ivp=id;T.day=S.day;T.msg='Saved you a spot in my grove. One small investment a week and we both grow.';go('inv-day')}
def('inv-perm',()=>({cls:'dark',html:`${topbar({close:true})}<div class="body center" style="display:flex;flex-direction:column;justify-content:center;align-items:center">
  <div class="sk-badge" style="width:72px;height:72px;border-radius:36px">${ic('user',30,'color:#74c947')}</div><div class="h2 mt24" style="color:#fff">Find someone to invite.</div>
  <p class="p mt8" style="max-width:300px">We use contacts only to show who’s already on Acorns. We never message anyone. You send the invite yourself.</p></div>
  ${foot(btn('Continue',"invPermSheet()",'wh'),btn('Share a link instead',"T.ivp='link';T.day=S.day;replace('inv-day')",'ghost'))}`}));
function invPermSheet(){sheet(`<div class="center" style="padding:6px 4px"><div style="font-weight:600;font-size:17px">“Acorns” Would Like to Access Your Contacts</div><p class="sm mt8">Shows which of your contacts already use Acorns.</p></div>
  <div class="mt16">${btn('Allow Full Access',"closeOv();S.perm.contacts='full';save();setTimeout(()=>replace('inv-contacts'),250)",'line','style="color:#007aff"')}</div><div class="mt8">${btn('Select Contacts…',"closeOv();S.perm.contacts='limited';save();setTimeout(()=>replace('inv-contacts'),250)",'line','style="color:#007aff"')}</div><div class="mt8">${btn('Don’t Allow',"closeOv();S.perm.contacts='denied';save();toast('No problem. Share a link instead.')",'ghost','style="color:#007aff"')}</div>`,{cls:'ios'})}
def('inv-contacts',()=>{if(T.cq===undefined)T.cq='';const ids=['jess','marcus','leo','nina','sam','priya'].filter(id=>!inGrove(id)&&PEOPLE[id].full.toLowerCase().indexOf(T.cq.toLowerCase())>-1);
  return {cls:'dark',html:`${topbar({title:'Contacts'})}<div class="body"><input class="inp" placeholder="Search" value="${T.cq}" oninput="T.cq=this.value;const c=this.selectionStart;refresh();const i=$('.inp',cur());i.focus();i.setSelectionRange(c,c)" aria-label="Search contacts">
  ${S.perm.contacts==='limited'?`<p class="sm mt8" style="color:var(--sk-sub)">Showing the contacts you selected.</p>`:''}
  <div class="mt12">${ids.map(id=>`<div class="sk-row" onclick="invStart('${id}')">${av(id,'s')}<div class="grow"><div class="t">${PEOPLE[id].full}</div><div class="s">${PEOPLE[id].phone}</div></div>${PEOPLE[id].on?`<span class="sk-chip" style="height:26px;font-size:11px">On Acorns</span>`:''}</div>`).join('')||`<p class="sm" style="color:var(--sk-sub)">No matches.</p>`}</div></div>`}});
def('inv-existing',p=>({cls:'dark',html:`${topbar({close:true})}<div class="body center" style="display:flex;flex-direction:column;justify-content:center;align-items:center">
  ${av(p.id,'l')}<div class="h2 mt16" style="color:#fff">${nm(p.id)} already has Acorns.</div><p class="p mt8" style="max-width:300px">No invite needed. Add them as a grove friend and they’ll get a request in their app. Referral rewards are for new investors only.</p></div>
  ${foot(btn('Add as grove friend',`S.grove.push({id:'${p.id}',status:'invited',day:S.day,req:1});save();toast('Request sent in the app');back()`,'wh'),btn('Not now','back()','ghost'))}`}));
def('inv-day',()=>{const who=T.ivp==='link'?'them':nm(T.ivp);const sug='Fri';if(!T.day)T.day=S.day;
  return {cls:'dark',html:`${topbar({title:''})}<div class="body"><div class="h2" style="color:#fff">Pick ${T.ivp==='link'?'their':nm(T.ivp)+'’s'} day.</div><p class="p mt8">A shared rhythm, not a rule. Any day they invest still counts.</p>
  ${hillRow([{html:`<img src="${IMG[rstage(S.streak)[2]]}" style="height:${rstage(S.streak)[2]==='acorn'?52:80}px">`,label:`You · ${S.day}`,me:1},{html:spot(`<img src="${IMG.acorn}" style="height:24px">`),label:`${who} · ${T.day}`}],{h:200})}
  <div class="chips mt16"><button class="chip ${T.day===S.day?'on':''}" onclick="T.day=S.day;refresh()">Same day as me</button><button class="chip ${T.day===sug&&T.day!==S.day?'on':''}" onclick="T.day='${sug}';refresh()">${ic('spark',14)} Fridays often work for paydays</button></div>
  <div class="days mt12">${DAYS7.map(d=>`<button class="${T.day===d?'on':''}" onclick="T.day='${d}';haptic(5);refresh()">${d}${d===S.day?'<span class="me"></span>':''}</button>`).join('')}</div>
  <div class="sm mt24" style="color:var(--sk-sub)">Message (optional)</div><textarea class="msgbox mt8" maxlength="160" oninput="T.msg=this.value" aria-label="Message">${T.msg||''}</textarea></div>
  ${foot(btn('Review','go(\'inv-review\')','wh'))}`}});
def('inv-review',()=>{const who=T.ivp==='link'?null:T.ivp;const card=storyCard({eyebrow:'Grow with me',title:`${S.me} saved you a spot.`,sub:`I invest on ${({Mon:'Monday',Tue:'Tuesday',Wed:'Wednesday',Thu:'Thursday',Fri:'Friday',Sat:'Saturday',Sun:'Sunday'})[T.day]||T.day}s. Pick your day too.`,foot:'acorns.com/j/jordan'});
  return {cls:'dark',html:`${topbar({title:'Review'})}<div class="body"><div style="width:190px;margin:0 auto">${card}</div>
  <div class="sk-list mt16"><div class="li"><div class="grow k">To</div><div class="v">${who?PEOPLE[who].full:'Anyone with the link'}</div></div><div class="li"><div class="grow k">Their day</div><div class="v">${T.day}</div></div><div class="li"><div class="grow k">Message</div><div class="v" style="max-width:190px;font-weight:500">${(T.msg||'None')}</div></div></div>
  <p class="sm mt12" style="color:var(--sk-sub)">You send it from your own Messages. The card never shows amounts. Their tree appears after their first investment.</p></div>
  ${foot(btn(`${ic('share',18)} Send invite`,"invSend()",'wh'))}`}});
function invSend(){const id=T.ivp==='link'?'nina':T.ivp;const card=storyCard({eyebrow:'Grow with me',title:`${S.me} saved you a spot.`,sub:`I invest on ${({Mon:'Monday',Tue:'Tuesday',Wed:'Wednesday',Thu:'Thursday',Fri:'Friday',Sat:'Saturday',Sun:'Sunday'})[T.day]||T.day}s.`});
  share({title:`${S.me} saved you a spot`,story:card,people:T.ivp==='link'?undefined:[id],text:T.msg,done:()=>{if(!inGrove(id))S.grove.push({id,status:'invited',day:T.day,sent:Date.now()});save();go('inv-waiting',{id})}})}
def('inv-waiting',p=>{const g=inGrove(p.id)||{day:'Fri'};return {cls:'dark',html:`${topbar({close:"home('gt-home')",title:''})}<div class="body">
  ${hillRow([{html:`<img src="${IMG[rstage(S.streak)[2]]}" style="height:${rstage(S.streak)[2]==='acorn'?52:84}px">`,label:'You',me:1},{html:spot(ic('oak',18)),label:'Waiting'}],{h:230})}
  <div class="h2 mt16" style="color:#fff">Invite sent · ${g.day}</div><p class="p mt8">${nm(p.id)}’s spot is saved. Their tree appears beside yours after their first investment, not at sign-up.</p>
  <div class="row mt16" style="gap:8px"><button class="btn line sm" style="color:#fff" onclick="gsRemind('${p.id}')">Remind</button><button class="btn line sm" style="color:#fff" onclick="T={ivp:'${p.id}',day:'${g.day}'};go('inv-day')">Change day</button><button class="btn line sm" style="color:#f39bb6" onclick="S.grove=S.grove.filter(x=>x.id!=='${p.id}');save();toast('Invite canceled');home('gt-home')">Cancel</button></div>
  <div class="mt24 center"><span class="sim" onclick="replace('inv-joined',{id:'${p.id}'})">${ic('ff',12)} Prototype: ${nm(p.id)} signs up</span></div></div>
  ${foot(btn('Done',"home('gt-home')",'wh'))}`}});
def('inv-joined',p=>({cls:'dark',html:`${topbar({close:"home('gt-home')"})}<div class="body center" style="display:flex;flex-direction:column;justify-content:center">
  ${hillRow([{html:`<img src="${IMG[rstage(S.streak)[2]]}" style="height:${rstage(S.streak)[2]==='acorn'?52:84}px">`,label:'You',me:1},{html:spot(`<img class="grow-in" src="${IMG.acorn}" style="height:26px">`),label:`${nm(p.id)} · seed`}],{h:240})}
  <div class="eyebrow mt16">Your grove</div><div class="h1 mt8">${nm(p.id)} signed up.</div><p class="p mt8">Their seed is in the ground. It sprouts when they make their first investment.</p>
  <div class="mt24"><span class="sim" onclick="replace('inv-tree',{id:'${p.id}'})">${ic('ff',12)} Prototype: ${nm(p.id)} invests</span></div></div>${foot(btn('Done',"home('gt-home')",'wh'))}`}));
def('inv-tree',p=>{const g=inGrove(p.id);if(g){g.status='growing';g.side=1;g.open=false}else S.grove.push({id:p.id,status:'growing',side:1});addFlourish('tree');save();
  return {cls:'dark',html:`<div class="body center" style="padding-top:calc(var(--safeTop) + 30px);display:flex;flex-direction:column">
  ${hillRow([{html:`<img src="${IMG[rstage(S.streak)[2]]}" class="breathe-once" style="height:${rstage(S.streak)[2]==='acorn'?52:90}px">`,label:'You',me:1},{html:`<img class="grow-in" src="${IMG.seedling}" style="height:80px">`,label:nm(p.id)}],{h:300})}
  <div class="eyebrow mt16">A new tree</div><div class="h1 mt8">You’re growing beside ${nm(p.id)}.</div><p class="p mt8">${nm(p.id)} made their first investment. Week 1, side by side.</p>
  <div class="card dk mt16" style="text-align:left;padding:12px 14px"><div class="sm" style="color:var(--sk-sub)">You’ll get your referral bonus per the Referrals program. <span class="link" style="font-size:13px">Terms</span></div></div></div>
  <div class="gm-row on">${btn(`${ic('share',18)} Share`,"go('share-b',{kind:'oak'})",'line','style="color:#fff;flex:1"')}${btn(`${ic('user',18)} Add to grove`,"T={};go('inv-pick')",'line','style="color:#fff;flex:1"')}</div><div class="gm-row on" style="padding-top:0">${btn('Done',"home('gt-home')",'wh')}</div>`,
  mount(el){ART.confetti(el,30);haptic(30)}}});
def('inv-expired',()=>({cls:'dark',html:`${topbar({close:true})}<div class="body center" style="display:flex;flex-direction:column;justify-content:center;align-items:center">
  <div class="spot" style="width:72px;height:72px;border-radius:36px">${ic('oak',28)}</div><div class="h2 mt24" style="color:#fff">Leo’s invite expired.</div><p class="p mt8" style="max-width:300px">Invites last 30 days. The spot is still yours. Send a fresh one, or free the spot.</p></div>
  ${foot(btn('Send a new invite',"T={ivp:'leo',day:S.day,msg:'Still saving you a spot.'};go('inv-day')",'wh'),btn('Free the spot',"S.grove=S.grove.filter(x=>x.id!=='leo');save();back();toast('Spot freed')",'ghost'))}`}));
/* friend side: pick your day too */
def('fr-day',()=>{if(!T.fd)T.fd='Fri';return {cls:'dark',html:`${topbar({close:"home('menu')",title:''})}<div class="body"><div class="eyebrow">Sam’s view</div><div class="h2 mt8" style="color:#fff">Jordan invests on Fridays. Pick your day too.</div><p class="p mt8">The same day makes it easier to keep going together. Any day still counts.</p>
  ${hillRow([{html:`<img src="${IMG.oak}" style="height:84px">`,label:'Jordan · Fri'},{html:`<img src="${IMG.acorn}" style="height:46px">`,label:`You · ${T.fd}`,me:1}],{h:210})}
  <div class="days mt16">${DAYS7.map(d=>`<button class="${T.fd===d?'on':''}" onclick="T.fd='${d}';refresh()">${d}${d==='Fri'?'<span class="me"></span>':''}</button>`).join('')}</div>
  <div class="vis mt16"><div><span>First investment</span><b>$5 on ${T.fd}</b></div><div><span>Streak</span><b>Week 1 starts</b></div></div></div>
  <div class="foot">${holdBtn('invest $5','go(\'fr-beside\')','light')}</div>`}});
def('fr-beside',()=>({cls:'dark',html:`<div class="body center" style="padding-top:calc(var(--safeTop) + 30px)">${hillRow([{html:`<img src="${IMG.oak}" style="height:90px">`,label:'Jordan'},{html:`<img class="grow-in" src="${IMG.seedling}" style="height:76px">`,label:'You',me:1}],{h:300})}
  <div class="eyebrow mt16">Week 1</div><div class="h1 mt8">You’re growing beside Jordan.</div><p class="p mt8">You see each other’s oaks and weeks. Never balances.</p></div>
  ${foot(btn('Done',"home('menu')",'wh'),btn('Find my money type',"T={};home('mt2-intro')",'ghost'))}`,mount(el){ART.confetti(el,30)}}));
def('water-set',()=>({cls:'dark',html:`${topbar({title:'Rain'})}<div class="body"><p class="p" style="margin-top:0">When your usual day passes and you haven’t invested yet, people you allow can send rain as a gentle nudge. They never see why, and never amounts.</p>
  <div class="sk-sec"><div class="h4">Let them water me</div></div>
  ${growing().map(g=>`<div class="card dk mt8" style="padding:12px 14px"><div class="row">${av(g.id,'s')}<div class="grow"><div style="font-weight:600;color:#fff">${PEOPLE[g.id].full}</div><div class="sm" style="color:var(--sk-sub)">At most once a week</div></div><div class="tog ${S.waterOK[g.id]?'on':''}" onclick="S.waterOK['${g.id}']=!S.waterOK['${g.id}'];save();refresh()"></div></div></div>`).join('')||'<p class="sm">Plant someone first.</p>'}</div>`}));

/* ================= 4.3 Future Club · Sapling ================= */
const SAP0=()=>({kid:'Ava',approve:true,leaves:[{id:'n1',from:'mom',name:'Grandma',text:'For your first bike, and every adventure after. Love you to the moon.',yr:1},{id:'n2',from:'dad',name:'Grandpa',text:'Save a little, dream a lot.',yr:1},{id:'n3',from:'priya',name:'Priya',text:'Happy first birthday, little one!',yr:2}],
  pending:[{id:'p1',from:'sam',name:'Sam',text:'Can’t wait to see who you become. Here’s to the long game.'},{id:'p2',from:'mom',name:'Grandma',text:'A little something for your second birthday.'}],members:['mom','dad','priya','sam'],yrs:3});
def('fc-types',()=>({cls:'dark',html:`${topbar({close:true,title:'Future Club'})}<div class="body"><div class="h1" style="color:#fff">Who is this club for?</div><p class="p mt8">Notes from people who care, kept until the moment they matter.</p>
  <div class="mt24"><div class="qcard" onclick="T={};go('fc-why1')"><div class="qi"><img src="${IMG.learn}" alt=""></div><div class="grow"><div class="ql">For me</div><div class="qs">A capsule. Friends add notes that open on a date you pick.</div></div>${ic('chev',16,'color:rgba(255,255,255,.4)')}</div>
  <div class="qcard" onclick="go(S.plan==='Gold'?(S.sap?'sap-home':'sap-new'):'sap-gold')"><div class="qi"><img src="${IMG.early}" alt=""></div><div class="grow"><div class="ql">For my kid</div><div class="qs">A sapling. Family adds notes and, if they like, a gift.</div></div><span class="sk-chip" style="height:24px;font-size:11px;color:#f5c451">Gold</span></div>
  <div class="qcard dis"><div class="qi">${ic('spark',22)}</div><div class="grow"><div class="ql">For someone’s big moment</div><div class="qs">Graduation, wedding, new baby.</div></div><span class="sk-chip" style="font-size:11px">Coming soon</span></div></div></div>`}));
def('sap-gold',()=>({cls:'dark',html:`${topbar({close:true})}<div class="body center" style="display:flex;flex-direction:column;justify-content:center;align-items:center"><img src="${IMG.early}" style="height:110px" alt="">
  <div class="h2 mt24" style="color:#fff">Future Club is part of Gold.</div><p class="p mt8" style="max-width:300px">Gold includes Acorns Early, so family can gift straight to your kid’s account through Giftlinks.</p>
  <div class="sk-list mt16" style="text-align:left;width:100%"><div class="li"><div class="grow k">Your plan</div><div class="v">${S.plan}</div></div><div class="li"><div class="grow k">Gold</div><div class="v">$12/mo (placeholder)</div></div></div></div>
  ${foot(btn('Upgrade to Gold',"S.plan='Gold';save();replace('sap-new');toast('Gold (simulated)')",'wh'),btn('Not now','back()','ghost'))}`}));
def('sap-new',()=>{if(!T.sn)T.sn={kid:'Ava',approve:true,first:true};const n=T.sn;return {cls:'dark',html:`${topbar({title:'New club'})}<div class="body"><div class="h2" style="color:#fff">Start ${n.kid||'their'}’s Future Club.</div>
  <div class="sm mt16" style="color:var(--sk-sub)">Kid’s first name</div><input class="inp mt8" value="${n.kid}" oninput="T.sn.kid=this.value" aria-label="First name">
  <div class="sm mt16" style="color:var(--sk-sub)">Linked Early account</div><div class="sk-row">${`<div class="sk-badge"><img src="${IMG.early}" alt=""></div>`}<div class="grow"><div class="t">${n.kid}’s Early account</div><div class="s">The sapling grows as you approve notes. It never shows the account balance.</div></div></div>
  <div class="card dk mt16" style="padding:4px 16px">${[['approve','Notes need my approval','Nothing shows until you approve it.'],['first','First name only','Writers never see a last name or photo.']].map(([k,l,s])=>`<div class="li" style="cursor:default;border-color:rgba(255,255,255,.08)"><div class="grow"><div class="ttl" style="color:#fff;font-size:15px">${l}</div><div class="sub" style="color:var(--sk-sub)">${s}</div></div><div class="tog ${n[k]?'on':''}" onclick="T.sn['${k}']=!T.sn['${k}'];refresh()"></div></div>`).join('')}</div></div>
  ${foot(btn('Create club',"S.sap=Object.assign(SAP0(),{kid:T.sn.kid||'Ava',approve:T.sn.approve});save();replace('sap-home')",'wh'))}`}});
function sapScene(h,newLeaf){const sp=S.sap;return `<div class="sk-hero" style="height:${h}px;margin:0 calc(-1*var(--pad))">${hills({dark:1})}<div class="hr-row" style="justify-content:center;gap:56px"><div class="hr-it"><img src="${IMG[rstage(S.streak)[2]]}" style="height:${{acorn:64,seedling:96,oak:120}[rstage(S.streak)[2]]}px"><div class="hr-lbl me">You</div></div>
  <div class="hr-it"><img src="${IMG.seedling}" style="height:84px"><div class="hr-lbl">${sp.kid}</div><div style="position:absolute;bottom:56px;left:50%;transform:translateX(-50%);display:flex;gap:3px">${sp.leaves.slice(-5).map((l,i)=>`<i class="leaf ${newLeaf&&i===Math.min(4,sp.leaves.length-1)?'new':''}" style="width:16px;height:16px;border-radius:16px 2px 16px 2px;display:block"></i>`).join('')}</div></div></div></div>`}
def('sap-home',p=>{spInit();if(!S.sap)S.sap=SAP0();const sp=S.sap;return {cls:'dark',html:`${heroTop(sapScene(280,p&&p.nl))}<div class="body" style="padding-top:12px">
  <div class="sk-title" style="font-size:26px;text-align:left;margin:0">${sp.kid}’s Future Club</div><div class="sm mt4" style="color:var(--sk-sub)">${sp.leaves.length} notes · ${sp.members.length} members · Gold</div>
  ${sp.pending.length?`<div class="nbg mt16"><div class="k">Waiting for you</div><div class="t">${sp.pending.length} note${sp.pending.length>1?'s':''} to approve</div><div class="s">Nothing shows on ${sp.kid}’s sapling until you say so.</div><div class="acts"><button class="pbtn" onclick="go('sap-mod')">Review</button></div></div>`:''}
  <div class="sk-sec"><div class="h4">Notes</div><span class="sm" onclick="go('sap-rings')" style="cursor:pointer">Growth rings ${ic('chev',12)}</span></div>
  <div class="leafrow">${sp.leaves.map(l=>`<div class="leaf" onclick="go('sap-note',{id:'${l.id}'})" aria-label="Note from ${l.name}">${l.name[0]}</div>`).join('')}</div>
  <div class="sk-sec"><div class="h4">Club members</div></div><div class="row" style="gap:8px">${sp.members.map(id=>av(id,'s').replace(/>[A-Z]</,'>'+(({mom:'Grandma',dad:'Grandpa'})[id]||nm(id))[0]+'<')).join('')}<button class="spot" style="width:40px;height:40px;margin:0" onclick="go('sap-invite')" aria-label="Invite">${ic('plus',16)}</button></div>
  <div class="mt24">${skRow(`<img src="${IMG.later}" alt="">`,'Make a Club book','A keepsake of every note. Never gift amounts.','nav',"go('sap-book')")}${skRow(ic('gear',18,'color:#74c947'),'Club settings','Approval, link, delete club','nav',"go('sap-set')")}</div>
  <div style="height:16px"></div></div>${foot(btn('Invite friends and family',"go('sap-invite')",'wh'))}`}});
def('sap-invite',()=>{const sp=S.sap||SAP0();return {cls:'dark',html:`${topbar({title:'Invite'})}<div class="body">
  <div class="sm" style="color:var(--sk-sub)">What they’ll see</div>
  <div class="card mt8" style="background:#f4f8ef;color:#191919;padding:16px;border-radius:20px"><div class="row"><img src="${IMG.seedling}" style="height:56px"><div class="grow"><div style="font-weight:600;font-size:16px">Add a note to ${sp.kid}’s Future Club</div><div class="sm" style="color:#555">From ${S.me} · no sign-in needed to write</div></div></div></div>
  <div class="card dk mt16" style="padding:4px 16px"><div class="li" style="cursor:default;border-color:rgba(255,255,255,.08)"><div class="grow"><div class="ttl" style="color:#fff;font-size:15px">Notes need my approval</div></div><div class="tog ${sp.approve?'on':''}" onclick="S.sap.approve=!S.sap.approve;save();refresh()"></div></div></div>
  <div class="sm mt16" style="color:var(--sk-sub)">Message to the club (optional)</div><textarea class="msgbox mt8" aria-label="Message">Write ${sp.kid} something for later. A note, a wish, a story.</textarea>
  <p class="sm mt12" style="color:var(--sk-sub)">Link getting passed around too much? <span class="link" style="font-size:13px" onclick="toast('Old link turned off. New link ready.')">Reset the link</span></p></div>
  ${foot(btn(`${ic('share',18)} Share invite`,`share({title:'Add a note to ${sp.kid}’s Future Club',story:storyCard({eyebrow:'Future Club',title:'Add a note to ${sp.kid}’s future.',sub:'No sign-in needed to write.',art:'<img src=&quot;'+IMG.seedling+'&quot; alt=&quot;&quot;>'})})`,'wh'),btn(`${ic('link',18)} Copy link`,"toast('Link copied')",'ghost'))}`}});
function sapDecide(id,ok){const sp=S.sap;const i=sp.pending.findIndex(n=>n.id===id);if(i<0)return;const n=sp.pending.splice(i,1)[0];if(ok){n.yr=sp.yrs;sp.leaves.push(n);haptic(15)}save();if(ok){T.lastLeaf=n.id;toast(`A leaf bloomed for ${n.name}`)}else toast('Hidden. They’ll still see “pending”.');refresh()}
def('sap-mod',()=>{const sp=S.sap||(S.sap=SAP0());return {cls:'dark',html:`${topbar({title:'Approve notes'})}<div class="body"><p class="p" style="margin-top:0">Swipe right to approve, left to hide. Hidden notes stay “pending” for the writer.</p>
  <div class="mt16">${sp.pending.map(n=>`<div class="swipe" data-id="${n.id}"><div class="bg"><span class="ok">Approve</span><span class="no">Hide</span></div><div class="fg" onpointerdown="swDown(event,this)"><div class="row">${av(n.from,'s').replace(/>[A-Z]</,'>'+(n.name||'?')[0]+'<')}<div class="grow"><div style="font-weight:600;color:#fff">${n.name}</div><div class="sm" style="color:var(--sk-sub)">Pending</div></div></div><p class="p mt8" style="color:#fff;margin-bottom:0">${n.text}</p>
   <div class="row mt12" style="gap:8px"><button class="btn wh sm" style="height:36px" onclick="sapDecide('${n.id}',1)">Approve</button><button class="btn line sm" style="height:36px;color:#fff" onclick="sapDecide('${n.id}',0)">Hide</button><button class="link" style="font-size:13px;margin-left:auto" onclick="toast('Reported. Our team will review it.');sapDecide('${n.id}',0)">Report</button></div></div></div>`).join('')||`<div class="center" style="padding:40px 0"><img src="${IMG.seedling}" style="height:80px"><div class="h3 mt16" style="color:#fff">All caught up.</div></div>`}</div>
  ${sp.pending.filter(n=>n.from==='mom').length>1||sp.pending.length>1?`<div class="mt8">${btn('Approve all from Grandma',"S.sap.pending.filter(n=>n.from==='mom').map(n=>n.id).forEach(id=>sapDecide(id,1))",'line','style="color:#fff"')}</div>`:''}</div>
  ${foot(btn('Done',"back()",'wh'))}`}});
function swDown(e,fg){const sx=e.clientX;let dx=0;fg.style.transition='none';fg.setPointerCapture(e.pointerId);
  fg.onpointermove=ev=>{dx=ev.clientX-sx;fg.style.transform=`translateX(${dx}px)`};fg.onpointerup=()=>{fg.onpointermove=null;fg.style.transition='';const id=fg.parentNode.dataset.id;if(dx>90){fg.style.transform='translateX(110%)';setTimeout(()=>sapDecide(id,1),200)}else if(dx<-90){fg.style.transform='translateX(-110%)';setTimeout(()=>sapDecide(id,0),200)}else fg.style.transform=''}}
def('sap-note',p=>{const sp=S.sap||SAP0();const n=sp.leaves.find(l=>l.id===p.id)||sp.leaves[0];return {cls:'dark',html:`${topbar({title:''})}<div class="body center" style="display:flex;flex-direction:column;justify-content:center">
  <div class="leaf new" style="width:72px;height:72px;margin:0 auto;font-size:24px">${n.name[0]}</div>
  <div class="card mt24" style="background:#f9f8f1;color:#191919;text-align:left;padding:22px;border-radius:22px"><div class="sm" style="color:#777">For ${sp.kid} · year ${n.yr||1}</div><p style="font-size:19px;line-height:1.45;margin:10px 0 0">${n.text}</p><div style="font-weight:600;margin-top:14px">${n.name}</div></div>
  <div class="chips mt16" style="justify-content:center">${['Thank you!','So kind','Ava will love this'].map(t=>`<button class="chip" onclick="toast('Sent ${n.name} “${t}”')">${t}</button>`).join('')}</div></div>
  ${foot(btn(`Save to ${sp.kid}’s keepsakes`,"toast('Saved to keepsakes');back()",'wh'),btn('Remove this note',`S.sap.leaves=S.sap.leaves.filter(l=>l.id!=='${n.id}');save();back();toast('Removed')`,'ghost'))}`}});
def('sap-rings',()=>{const sp=S.sap||SAP0();const yr=T.ring||Math.max(1,...sp.leaves.filter(l=>l.ok!==false).map(l=>l.yr||1));return {cls:'dark',html:`${topbar({title:'Growth rings'})}<div class="body"><p class="p" style="margin-top:0">A ring for every birthday. Tap one to replay that year’s notes.</p>
  <div class="rings">${Array.from({length:sp.yrs},(_,k)=>{const r=k+1;const s=70+k*80;return `<i class="${yr===r?'on':''}" style="width:${s}px;height:${s}px" onclick="T.ring=${r};haptic(6);refresh()" aria-label="Year ${r}"></i>`}).join('')}<img src="${IMG.seedling}" style="position:absolute;left:50%;top:50%;height:44px;transform:translate(-50%,-50%)"></div>
  <div class="sk-sec"><div class="h4">Year ${yr}</div><span class="sm">${sp.leaves.filter(l=>(l.yr||1)===yr).length} notes</span></div>
  ${sp.leaves.filter(l=>(l.yr||1)===yr).map(l=>skRow(`<div class="leaf" style="width:32px;height:32px;font-size:11px">${l.name[0]}</div>`,l.name,l.text.slice(0,48)+(l.text.length>48?'…':''),'nav',`go('sap-note',{id:'${l.id}'})`)).join('')||'<p class="sm" style="color:var(--sk-sub)">No notes this year yet.</p>'}</div>`}});
def('sap-book',()=>{const sp=S.sap||SAP0();return {cls:'dark',html:`${topbar({title:'Club book'})}<div class="body"><div class="row" style="gap:12px;overflow-x:auto;padding:8px 0 14px;scrollbar-width:none">
  <div style="flex-shrink:0;width:180px;height:240px;border-radius:12px;background:linear-gradient(160deg,#2e6b1a,#0b1f09);color:#fff;padding:18px;display:flex;flex-direction:column;justify-content:space-between"><img src="${IMG.seedling}" style="height:56px;align-self:flex-start"><div><div style="font-size:22px;font-weight:600;line-height:1.1;color:#fff!important">${sp.kid}’s Future Club</div><div class="sm" style="color:rgba(255,255,255,.75)!important;margin-top:6px">${sp.leaves.length} notes · ${sp.yrs} years</div></div></div>
  ${sp.leaves.slice(0,3).map(l=>`<div style="flex-shrink:0;width:180px;height:240px;border-radius:12px;background:#f9f8f1;color:#191919;padding:18px;display:flex;flex-direction:column"><div class="sm" style="color:#888">Year ${l.yr||1}</div><p style="font-size:14px;line-height:1.45;flex:1">${l.text}</p><b style="font-size:13px">${l.name}</b></div>`).join('')}</div>
  <div class="sk-list"><div class="li"><span class="sk-ck" style="width:20px;height:20px">${ic('check',12)}</span><div class="grow" style="font-size:14px">Notes, first names and dates</div></div><div class="li"><span class="sk-ck" style="width:20px;height:20px">${ic('check',12)}</span><div class="grow" style="font-size:14px">Never gift amounts</div></div><div class="li"><span class="sk-ck" style="width:20px;height:20px">${ic('check',12)}</span><div class="grow" style="font-size:14px">Nothing is sent by Acorns. You save or share it.</div></div></div></div>
  ${foot(btn('Save PDF',"toast('Saved to Files')",'wh'),btn(`${ic('share',18)} Share`,"share({title:'Club book',story:storyCard({eyebrow:'Future Club',title:'Ava’s Club book',art:'<img src=&quot;'+IMG.seedling+'&quot; alt=&quot;&quot;>'})})",'ghost'))}`}});
def('sap-set',()=>({cls:'dark',html:`${topbar({title:'Club settings'})}<div class="body">${skRow(ic('check',18,'color:#74c947'),'Notes need my approval',S.sap&&S.sap.approve?'On':'Off',null,'')}${skRow(ic('link',18,'color:#74c947'),'Reset invite link','Turns off the old link',null,"toast('New link ready')")}${skRow(ic('close',18,'color:#f39bb6'),'Delete club','Notes are removed for everyone',null,"sheet('<div class=&quot;h3&quot;>Delete Ava’s club?</div><p class=&quot;p mt8&quot;>Notes are removed for everyone. Gifts already in Ava’s Early account stay there.</p><div class=&quot;mt24&quot;>'+btn('Delete club','closeOv();S.sap=null;save();home(\\'gt-home\\');toast(\\'Club deleted\\')','dk')+'</div><div class=&quot;mt8&quot;>'+btn('Not now','closeOv()','ghost','style=&quot;color:#555&quot;')+'</div>')")}</div>`}));
/* friend side */
def('sapf-land',()=>({cls:'dark',html:`${topbar({close:"home('menu')",title:'acorns.com',right:'<div style="width:44px"></div>'})}<div class="body center" style="display:flex;flex-direction:column">
  <div class="sk-hero" style="height:280px">${hills({dark:1})}<div class="tree"><img src="${IMG.seedling}" style="height:120px"></div></div>
  <div class="eyebrow mt16">From Jordan</div><div class="h1 mt8">Add a note to Ava’s Future Club.</div><p class="p mt8">Ava will read it when she’s older. No account or sign-in needed to write.</p></div>
  ${foot(btn('Write a note',"T.fn=T.fn||'';go('sapf-write')",'wh'))}`}));
def('sapf-write',()=>({cls:'dark',html:`${topbar({title:'Your note'})}<div class="body"><textarea class="msgbox" style="min-height:160px" maxlength="300" placeholder="Something Ava should hear one day…" oninput="T.fn=this.value;$('#fnc').textContent=this.value.length+' / 300';$('#fnp').textContent=this.value||'Your note'" aria-label="Note">${T.fn||''}</textarea><div class="sm mt8" style="text-align:right;color:var(--sk-sub)" id="fnc">${(T.fn||'').length} / 300</div>
  <div class="sm mt16" style="color:var(--sk-sub)">Preview</div><div class="row mt8" style="gap:12px;align-items:flex-start"><div class="leaf" style="flex-shrink:0">Y</div><div class="card" style="background:#f9f8f1;color:#191919;flex:1;padding:14px;border-radius:16px;font-size:14px" id="fnp">${T.fn||'Your note'}</div></div>
  <div class="sm mt16" style="color:var(--sk-sub)">Your first name</div><input class="inp mt8" value="Sam" aria-label="Your first name"></div>
  ${foot(btn('Continue',"go('sapf-gift')",'wh'))}`}));
def('sapf-gift',()=>{if(T.fg===undefined)T.fg=25;return {cls:'dark',html:`${topbar({title:'Add a gift?'})}<div class="body"><div class="h2" style="color:#fff">Add a gift with a Giftlink.</div><p class="p mt8">Optional. It goes to Ava’s Early account. Only you and her parent see the amount.</p>
  <div class="chips mt16">${[10,25,50,100].map(v=>`<button class="chip ${T.fg===v?'on':''}" onclick="T.fg=${v};refresh()">$${v}</button>`).join('')}<button class="chip" onclick="keypad(T.fg,v=>{T.fg=v;refresh()},'Gift')">Other</button></div>
  <div class="vis mt16"><div><span>Gift</span><b>${money(T.fg)}</b></div><div><span>Goes to</span><b>Ava’s Early account</b></div><div><span>Pay with</span><b>Apple Pay</b></div><div><span>Shows on cards</span><b>Never</b></div></div>
  <p class="sm mt12" style="color:var(--sk-sub)">Gifts are not tax-deductible. Giftlink terms apply. <span class="link" style="font-size:13px">Details</span></p></div>
  ${foot(btn('Add '+money(T.fg)+' gift',"toast('Paid (simulated)');go('sapf-done',{g:1})",'wh'),btn('Just the note','go(\'sapf-done\')','ghost'))}`}});
def('sapf-done',p=>({cls:'dark',html:`<div class="body center" style="display:flex;flex-direction:column;justify-content:center;padding-top:calc(var(--safeTop) + 30px)"><div class="leaf new" style="width:80px;height:80px;margin:0 auto;font-size:26px">S</div>
  <div class="h1 mt24">Your note is on its way.</div><p class="p mt8">Ava’s parent approves each note before it’s added to her sapling.${p.g?' Your gift is headed to her Early account.':''}</p>
  <div class="card dk mt24" style="text-align:left"><div style="font-weight:600;color:#fff">Start your own grove?</div><p class="sm mt4" style="color:var(--sk-sub)">Invest a little each week. Watch your own oak grow.</p></div></div>
  ${foot(btn('Get started',"T={};home('mt2-intro')",'wh'),btn('Done',"home('menu')",'ghost'))}`}));

/* ================= 4.4 Stories engine · Recap · Journal · Year ================= */
let STP=null;
function stories(id,slides,o){o=o||{};const i=Math.min(T.si||0,slides.length-1);const s=slides[i];
  return {cls:'dark',html:`<div class="stp" style="background:${s.bg||'linear-gradient(180deg,#123a0d,#0b1f09)'}"><div class="stbars">${slides.map((_,k)=>`<i class="${k<i?'done':k===i?'on':''}"><b></b></i>`).join('')}</div>
  <div class="row" style="padding:10px 12px 0;justify-content:space-between"><div class="sk-chip" style="height:28px;font-size:12px">${o.label||'Acorns'}</div><button class="iconbtn" onclick="T.si=0;back()" aria-label="Close">${ic('close')}</button></div>
  <div class="stc" onpointerdown="stHold(1)" onpointerup="stHold(0,event)" onpointerleave="stHold(0)">${s.html}</div>${s.foot||''}</div>`,
  mount(el){clearTimeout(STP);if(i<slides.length-1&&!o.manual)STP=setTimeout(()=>{if(cur()===el){T.si=i+1;refresh()}},5200);if(s.mount)s.mount(el)}}}
let STH=0;function stHold(d,e){const b=$('.stbars i.on b',cur());if(d){STH=Date.now();if(b)b.style.animationPlayState='paused';clearTimeout(STP);return}if(!STH)return;const held=Date.now()-STH>300;STH=0;if(b)b.style.animationPlayState='running';
  if(!e||held){refresh();return}const r=e.currentTarget.getBoundingClientRect();const left=e.clientX-r.left<r.width*.33;T.si=Math.max(0,(T.si||0)+(left?-1:1));refresh()}
const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
const JOURNAL=[{m:9,w:4,fl:['acorns'],tr:1,cap:'Two new leaves and a songbird'},{m:8,w:4,fl:['roots'],tr:2,cap:'Recurring ran every week'},{m:7,w:0,fl:[],tr:0,cap:'',quiet:1},{m:6,w:3,fl:[],tr:1,cap:'Sam joined your grove'},{m:5,w:2,fl:[],tr:0,cap:'You planted your first acorn'}];
def('recap',p=>{const j=JOURNAL.find(x=>x.m===(p.m===undefined?9:p.m))||JOURNAL[0];const M=MONTHS[j.m];
  if(j.quiet)return {cls:'dark',html:`${topbar({title:M})}<div class="body center" style="display:flex;flex-direction:column;justify-content:center"><div class="sk-hero" style="height:280px">${hills({dark:1})}<div class="tree"><img src="${IMG.seedling}" style="height:100px;opacity:.85"></div></div>
   <div class="h1 mt16">Quiet month.</div><p class="p mt8">Your oak is still here. Every flourish too.</p></div>${foot(btn('Back to Journal','back()','wh'))}`};
  const sl=[{html:`<div class="sk-hero" style="height:340px;margin:0">${hills({dark:1})}<div class="tree"><img class="grow-in" src="${IMG[rstage(S.streak||5)[2]]}" style="height:${{acorn:88,seedling:130,oak:160}[rstage(S.streak||5)[2]]}px"></div></div><div class="center" style="padding:0 28px"><div class="eyebrow">${M}</div><div class="h1 mt8">Your oak’s ${M}.</div><p class="p mt8">${j.cap}.</p></div>`},
    {html:`<div class="center" style="padding:60px 28px 0"><div style="font-size:120px;font-weight:600;color:#74c947;line-height:1">${j.w}</div><div class="h2 mt8" style="color:#fff">weeks invested</div><div class="row mt24" style="justify-content:center;gap:10px">${[0,1,2,3].map(k=>`<i style="width:26px;height:26px;border-radius:13px;display:block;background:${k<j.w?'#74c947':'rgba(255,255,255,.12)'}"></i>`).join('')}</div></div>`},
    {html:`<div class="center" style="padding:60px 28px 0">${j.fl.length?j.fl.map(k=>`<img class="grow-in" src="${IMG[FLIMG[k]]}" style="height:120px">`).join(''):`<img src="${IMG.seedling}" style="height:120px">`}<div class="h1 mt24">${j.fl.length?`New: ${j.fl.map(k=>FLNAME[k]).join(', ')}`:'Steady growth'}</div><p class="p mt8">${j.tr?`${j.tr} tree${j.tr>1?'s':''} planted in your grove.`:'Your grove grew quietly.'}</p></div>`},
    {html:`<div style="width:62%;margin:30px auto 0">${storyCard({eyebrow:`My ${M}`,title:j.cap+'.',sub:`${j.w} weeks invested.`})}</div>`,foot:`<div class="foot">${btn(`${ic('share',18)} Share`,`T.sbT=undefined;T.sbName=undefined;go('share-b',{kind:'recap'})`,'wh')}${btn('Not now',"T.si=0;back()",'ghost')}</div>`}];
  return stories('recap',sl,{label:`${M} recap`})});
def('journal',()=>({cls:'dark',html:`${topbar({title:'Journal'})}<div class="body"><p class="p" style="margin-top:0">A snapshot of your oak each month. In December, they become your Acorns Year.</p>
  <div class="mt16">${btn('Watch your Acorns Year',"T.si=0;go('year')",'wh')}</div>
  <div class="jl mt24">${JOURNAL.map(j=>`<div class="e ${j.quiet?'q':''}" onclick="T.si=0;go('recap',{m:${j.m}})" style="cursor:pointer"><div class="card dk" style="padding:12px 14px"><div class="row"><img src="${IMG[j.quiet?'seedling':j.m>7?'seedling':'acorn']}" style="height:48px;${j.quiet?'opacity:.5':''}"><div class="grow"><div style="font-weight:600;color:#fff">${MONTHS[j.m]}</div><div class="sm" style="color:var(--sk-sub)">${j.quiet?'Quiet month. Your oak is still here.':`${j.w} weeks · ${j.cap}`}</div></div>${ic('chev',16,'color:rgba(255,255,255,.4)')}</div></div></div>`).join('')}</div></div>`}));
def('year',p=>{p=p||{};const nu=p.newUser;const weeks=nu?3:41;const fl=nu?['roots']:['roots','acorns','nest','gold','bird'];const showN=!!T.yn;
  const sl=[{html:`<div class="sk-hero" style="height:380px;margin:0">${hills({dark:1})}<div class="tree"><img class="grow-in" src="${IMG[nu?'acorn':'oak']}" style="height:${nu?90:170}px"></div></div><div class="center" style="padding:0 28px"><div class="eyebrow">2026</div><div class="h1 mt8">Your Acorns Year</div>${nu?'<p class="p mt8">It’s just getting started. Here’s your first chapter.</p>':''}</div>`,bg:'linear-gradient(180deg,#1f4d17,#0b1f09)'},
    {html:`<div class="center" style="padding:40px 26px 0"><div style="font-size:110px;font-weight:600;color:#74c947;line-height:1">${weeks}</div><div class="h2 mt8" style="color:#fff">weeks invested</div><p class="p mt8">${nu?'Every one counts.':'Including a fresh start in July. Every week counted.'}</p><div class="cal52 mt24">${Array.from({length:52},(_,k)=>`<i data-k="${k}"></i>`).join('')}</div></div>`,
     mount(el){const on=nu?[49,50,51]:Array.from({length:52},(_,k)=>k).filter(k=>!(k>=26&&k<=36));on.forEach((k,n)=>setTimeout(()=>{const d=$(`.cal52 i[data-k="${k}"]`,el);if(d)d.classList.add('on')},n*45))}},
    {html:`<div class="center" style="padding:40px 26px 0"><div class="eyebrow">Your oak’s year</div><div style="height:260px;position:relative;margin-top:16px" id="tlapse"><img src="${IMG.acorn}" style="height:70px;position:absolute;left:50%;bottom:0;transform:translateX(-50%)"></div><div class="row mt16" style="justify-content:center;gap:8px" id="tlfl"></div></div>`,
     mount(el){const seq=nu?[['acorn',70],['seedling',110]]:[['acorn',70],['seedling',120],['oak',200]];seq.forEach(([k,h],n)=>setTimeout(()=>{const b=$('#tlapse',el);if(b)b.innerHTML=`<img class="grow-in" src="${IMG[k]}" style="height:${h}px;position:absolute;left:50%;bottom:0;transform:translateX(-50%)">`},n*900));
       fl.forEach((k,n)=>setTimeout(()=>{const r=$('#tlfl',el);if(r)r.insertAdjacentHTML('beforeend',`<img class="grow-in" src="${IMG[FLIMG[k]]}" style="height:36px">`)},600+n*500))}}];
  if(!nu)sl.push({html:`<div style="padding:40px 22px 0"><div class="eyebrow center">Highlights</div>${[['seedling','Most roots','26 weeks of recurring in a row'],['roundup','Most acorns','March: 4 acorns from Round-Ups'],['learn','A first','Your first songbird']].map(([im,t,s],n)=>`<div class="card dk mt12 rise d${n*2+1}" style="padding:14px"><div class="row"><img src="${IMG[im]}" style="height:44px"><div><div style="font-weight:600;color:#fff">${t}</div><div class="sm" style="color:var(--sk-sub)">${s}</div></div></div></div>`).join('')}</div>`});
  sl.push({html:`<div class="center" style="padding:30px 22px 0"><div class="eyebrow">Your grove</div><div class="h1 mt8">${nu?'1 tree planted':'4 trees planted'}</div>${hillRow(nu?[{html:`<img src="${IMG.acorn}" style="height:50px">`,label:'You',me:1},{html:spot(),label:'Invite'}]:[{html:`<img src="${IMG.seedling}" style="height:70px">`,label:showN?'Sam':'Friend'},{html:`<img src="${IMG.oak}" style="height:110px">`,label:'You',me:1},{html:`<img src="${IMG.oak}" style="height:90px">`,label:showN?'Mom':'Family'}],{h:230})}
    <div class="row mt16" style="justify-content:center;gap:10px"><span class="sm" style="color:var(--sk-sub)">Show names</span><div class="tog ${showN?'on':''}" onclick="event.stopPropagation();T.yn=!T.yn;refresh()" onpointerdown="event.stopPropagation()" onpointerup="event.stopPropagation()"></div></div></div>`});
  sl.push({html:`<div style="width:62%;margin:24px auto 0">${storyCard({eyebrow:'My Acorns Year',title:`${weeks} weeks invested.`,sub:`${fl.length} flourishes.`})}</div>`,foot:`<div class="foot">${btn(`${ic('share',18)} Share`,"T.sbT=undefined;T.sbName=undefined;go('share-b',{kind:'year'})",'wh')}${btn('Save image',"toast('Saved to Photos')",'ghost')}</div>`});
  return stories('year',sl,{label:'Acorns Year'})});

/* ================= 4.6 Money Manager split v2 ================= */
const FREQS=['Weekly','Every 2 weeks','Twice a month','Monthly'];
const PRESETS={Balanced:[60,25,15],'Growth-first':[80,15,5],'Safety-first':[40,20,40]};
function savingsLocked(){return !(S.plan==='Silver'||S.plan==='Gold')||S.noChecking}
def('mm2-pay',()=>{const p=S.pay;return {cls:'dark',html:`<div class="hero-wrap">${oakStage({h:280,flush:1,ghost:['roots','gold','nest']})}<div class="top"><button class="iconbtn" onclick="back()">${ic('back')}</button><div class="t" style="color:#fff">Split a paycheck</div><button class="iconbtn" onclick="protoMenu()">${ic('menu',22)}</button></div></div>
  <div class="body" style="padding-top:14px"><div class="h2" style="color:#fff">One paycheck, three habits.</div><p class="p mt8">Tell us about your pay. Only you see these numbers.</p>
  <div class="sm mt16" style="color:var(--sk-sub)">Paycheck amount</div><div class="amt" style="color:#fff;text-align:left;font-size:44px;margin:4px 0" onclick="keypad(S.pay.amt,v=>{S.pay.amt=v;save();refresh()},'Paycheck')">${money(p.amt)}</div>
  <div class="sm mt8" style="color:var(--sk-sub)">How often</div><div class="chips mt8">${FREQS.map(f=>`<button class="chip ${p.freq===f?'on':''}" onclick="S.pay.freq='${f}';save();refresh()">${f}</button>`).join('')}</div>
  <div class="sm mt16" style="color:var(--sk-sub)">Next payday</div><div class="chips mt8">${['Fri, Oct 30','Fri, Nov 6','Fri, Nov 13'].map(d=>`<button class="chip ${p.next===d?'on':''}" onclick="S.pay.next='${d}';save();refresh()">${d}</button>`).join('')}</div>
  <div class="card dk mt16"><div class="row"><div class="grow"><div style="font-weight:600;color:#fff">Remind me on payday</div><div class="sm" style="color:var(--sk-sub)">Your split, ready to confirm. No account access needed.</div></div><div class="tog ${p.remind?'on':''}" onclick="S.pay.remind=!S.pay.remind;save();refresh()"></div></div></div>
  <p class="center mt16"><span class="sim" onclick="S.pay.detected=true;save();go('mm2-split',{pre:1})">${ic('ff',12)} Prototype: paycheck detected</span></p></div>
  ${foot(btn('Continue',"go('mm2-split')",'wh'))}`}});
function mmSlices(){const sp=S.split;if(savingsLocked()){const t=sp.i+sp.l+sp.s;return {i:Math.round((sp.i+sp.s)/t*100/5)*5,l:100-Math.round((sp.i+sp.s)/t*100/5)*5,s:0}}return sp}
function mmDollars(pct){return Math.round(S.pay.amt*pct)/100}
def('mm2-split',p=>{p=p||{};const sl=mmSlices();const lock=savingsLocked();const mo=T.wi||6;const per={Weekly:4.3,'Every 2 weeks':2.15,'Twice a month':2,Monthly:1}[S.pay.freq]||2;
  const rootsW=Math.round(mo*4.3),gold=mo,nest=sl.s>0;const rows=[['i','Invest','seedling','#74c947','Counts toward your streak'],['l','Later','later','#f5c451','A gold leaf each month'],['s','Savings','moneybag','#8cc4f7','Your nest']];
  return {cls:'dark',html:`<div class="hero-wrap">${oakStage({h:270,flush:1,fl:[],ghost:['roots','gold'].concat(nest?['nest']:[]),id:'mmT'})}<div class="top"><button class="iconbtn" onclick="back()">${ic('back')}</button><div class="t" style="color:#fff">Your split</div><button class="iconbtn" onclick="protoMenu()">${ic('menu',22)}</button></div></div>
  <div class="body" style="padding-top:10px">
  ${p.pre?`<div class="nbg" style="padding:12px 14px"><div class="row"><div class="grow"><div class="k">Paycheck landed</div><div style="font-weight:600;margin-top:2px">${money(S.pay.amt)} · your last split is ready</div></div><button class="sbtn" onclick="S.pay.detected=false;S.pay.ignored=(S.pay.ignored||0)+1;save();back()">Not now</button></div></div>`:''}
  <div class="row between mt8"><span class="sm" style="color:var(--sk-sub)">In ${mo} months your oak would have</span></div><div class="sm mt4" style="color:#bceaa3;font-weight:600">${rootsW} weeks of roots · ${gold} gold leaves${nest?' · a nest':''}</div>
  <div class="scrub mt8">${[3,6,12].map(m=>`<button class="${mo===m?'on':''}" onclick="T.wi=${m};refresh()">${m} months</button>`).join('')}</div>
  <div class="sbar mt16" id="splitbar">${rows.map(([k,n,,c])=>sl[k]>0?`<div class="sl" data-k="${k}" style="width:${sl[k]}%;background:${c}">${sl[k]>=12?`<span>${n}</span><span style="opacity:.75">${sl[k]}%</span>`:''}</div>`:'').join('')}
   <div class="dv" data-d="1" style="left:${sl.i}%" onpointerdown="mmDrag(event,1)" role="slider" aria-label="Invest and Later divider" aria-valuenow="${sl.i}"><i></i></div>${lock?'':`<div class="dv" data-d="2" style="left:${sl.i+sl.l}%" onpointerdown="mmDrag(event,2)" role="slider" aria-label="Later and Savings divider" aria-valuenow="${sl.i+sl.l}"><i></i></div>`}</div>
  <div class="chips mt12">${Object.keys(PRESETS).map(k=>`<button class="chip ${PRESETS[k].join()===[S.split.i,S.split.l,S.split.s].join()?'on':''}" onclick="const v=PRESETS['${k}'];S.split={i:v[0],l:v[1],s:v[2]};save();haptic(8);refresh()">${k}</button>`).join('')}</div>
  <div class="mt16">${rows.map(([k,n,im,c,line])=>{const d=mmDollars(sl[k]);const small=sl[k]>0&&d<5;return `<div class="sk-row" style="${k==='s'&&lock?'opacity:.6':''}"><div class="sk-badge" style="border-color:${c}"><img src="${IMG[im]}" style="height:${18+Math.round(sl[k]/6)}px;max-height:30px" alt=""></div><div class="grow"><div class="t">${n} ${sl[k]?`· ${sl[k]}%`:''}</div><div class="s">${k==='s'&&lock?'Needs Acorns Checking on Silver or Gold':line}</div></div><div style="font-weight:600;color:#fff">${small?`<span class="sk-chip" style="height:24px;font-size:11px;color:#f8d38f">Too small</span>`:sl[k]?money(d):'—'}</div></div>`}).join('')}</div>
  ${lock?`<div class="lockrow mt8">${ic('lock',16)}<div class="grow">Savings needs Acorns Checking on Silver or Gold. Until then, that slice goes to Invest.</div><span class="link" style="font-size:13px" onclick="go('mm2-elig')">Here’s how</span></div>`:''}
  <p class="sm mt12" style="color:var(--sk-sub)">Oak extras shown are illustrative and based only on your schedule. Not a projection of returns or balances.</p></div>
  ${foot(btn('Review',"go('mm2-review')",'wh'))}`}});
function mmDrag(e,d){e.preventDefault();const bar=$('#splitbar');const r=bar.getBoundingClientRect();let last=null;const lock=savingsLocked();
  const mv=ev=>{let pct=Math.round(((ev.clientX-r.left)/r.width*100)/5)*5;const sp=Object.assign({},mmSlices());
    if(d===1){pct=Math.max(5,Math.min((lock?100:sp.i+sp.l)-(lock?5:0),pct));const end=sp.i+sp.l;sp.i=pct;sp.l=lock?100-pct:Math.max(0,end-pct)}else{pct=Math.max(sp.i,Math.min(100,pct));sp.l=pct-sp.i;sp.s=100-pct}
    if(lock){S.split={i:sp.i,l:sp.l,s:S.split.s}}else S.split=sp;if(last!==pct){last=pct;haptic(4);const s2=mmSlices();$$('#splitbar .sl').forEach(x=>{x.style.width=s2[x.dataset.k]+'%'});const d1=$('#splitbar .dv[data-d="1"]'),d2=$('#splitbar .dv[data-d="2"]');if(d1)d1.style.left=s2.i+'%';if(d2)d2.style.left=(s2.i+s2.l)+'%'}};
  const up=()=>{window.removeEventListener('pointermove',mv);window.removeEventListener('pointerup',up);save();refresh()};window.addEventListener('pointermove',mv);window.addEventListener('pointerup',up)}
def('mm2-elig',()=>({cls:'dark',html:`${topbar({close:true,title:'What each slice needs'})}<div class="body">
  ${[['seedling','Invest','Any plan','ok'],['later','Later (IRA)','Any plan','ok'],['moneybag','Savings','Acorns Checking on Silver or Gold',savingsLocked()?'no':'ok']].map(([im,n,req,st])=>`<div class="card dk mt8" style="padding:14px"><div class="row"><img src="${IMG[im]}" style="height:36px"><div class="grow"><div style="font-weight:600;color:#fff">${n}</div><div class="sm" style="color:var(--sk-sub)">${req}</div></div>${st==='ok'?`<span class="sk-ck" style="width:22px;height:22px">${ic('check',12)}</span>`:ic('lock',18,'color:#f8d38f')}</div></div>`).join('')}
  <p class="sm mt16" style="color:var(--sk-sub)">You’re on ${S.plan}${S.noChecking?' without Acorns Checking':''}.</p></div>
  ${savingsLocked()?foot(btn('Upgrade to Silver',"S.plan='Silver';S.noChecking=false;save();back();toast('Silver + Checking (simulated)')",'wh'),btn('Not now','back()','ghost')):foot(btn('Done','back()','wh'))}`}));
def('mm2-review',()=>{const sl=mmSlices();const rows=[['Invest',sl.i,'Invest account','Counts toward your streak'],['Later',sl.l,'Later (Roth IRA)','A gold leaf each month'],['Savings',sl.s,'Emergency Fund','Your nest']].filter(r=>r[1]>0);
  const ds=rows.map(r=>Math.floor(S.pay.amt*r[1])/100);const rem=Math.round((S.pay.amt-ds.reduce((a,b)=>a+b,0))*100)/100;ds[0]+=rem;
  return {cls:'dark',html:`${topbar({title:'Review'})}<div class="body"><div class="h2" style="color:#fff">Split ${money(S.pay.amt)}, ${S.pay.freq.toLowerCase()}.</div><p class="p mt8">First run ${S.pay.next}. Changes apply to the next paycheck.</p>
  <div class="sk-list mt16">${rows.map((r,k)=>`<div class="li"><div class="grow"><div style="font-weight:600">${r[0]} · ${r[1]}%</div><div class="sm" style="color:var(--sk-sub)">${r[2]} · ${r[3]}</div></div><div class="v">${money(ds[k])}</div></div>`).join('')}</div>
  <p class="sm mt12" style="color:var(--sk-sub)">If your paycheck is late or smaller, we split it by percent, not dollars, and let you know. Any rounding remainder goes to Invest. Investing involves risk. <span class="link" style="font-size:13px">Disclosures</span></p></div>
  <div class="foot">${holdBtn('split my paycheck','mm2Confirm()','light')}<div class="mt8">${btn('Change','back()','ghost')}</div></div>`}});
function mm2Confirm(){const sl=mmSlices();const ks=[];if(sl.i>0&&addFlourish('roots'))ks.push('roots');if(sl.l>0&&addFlourish('gold'))ks.push('gold');if(sl.s>0&&addFlourish('nest'))ks.push('nest');S.recurring=true;S.pay.detected=false;save();
  stack=stack.filter(s=>['mm2-pay','mm2-split','mm2-review','mm2-elig'].indexOf(s.id)<0);go('growth',{ks:ks.length?ks:[],eyebrow:'Paycheck split',cap:'Three habits, one paycheck.',sub:`Starts ${S.pay.next}.`,notice:'Your Invest slice keeps your streak going.',next:'finish'})}
def('mm2-late',()=>({cls:'dark',html:`${topbar({close:true})}<div class="body center" style="display:flex;flex-direction:column;justify-content:center;align-items:center"><img src="${IMG.later}" style="height:90px"><div class="h2 mt24" style="color:#fff">Your paycheck is running late.</div>
  <p class="p mt8" style="max-width:300px">Nothing moved. When it lands, we’ll split it by percent, so a smaller check still splits the same way.</p></div>${foot(btn('Got it','back()','wh'),btn('Edit split',"go('mm2-split')",'ghost'))}`}));
def('mm2-down',()=>({cls:'dark',html:`${topbar({close:true})}<div class="body center" style="display:flex;flex-direction:column;justify-content:center;align-items:center"><img src="${IMG.moneybag}" style="height:90px;opacity:.7"><div class="h2 mt24" style="color:#fff">Your Savings slice is paused.</div>
  <p class="p mt8" style="max-width:300px">Your plan changed to Bronze, which doesn’t include Acorns Checking. Send that ${S.split.s}% to Invest instead?</p></div>${foot(btn('Move it to Invest',"S.split={i:S.split.i+S.split.s,l:S.split.l,s:0};save();back();toast('Moved to Invest')",'wh'),btn('Not now','back()','ghost'))}`}));

